//! Durable replay from seeds and committed actions. Native checkpoint bytes are
//! regenerated by the replacement workers and verified against the saved journal digest.
use super::*;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::{
    fs::File,
    io::{BufWriter, Read, Seek, SeekFrom, Write},
    path::Path,
};

const MAGIC: &[u8; 8] = b"GZRECP02";
const LEGACY_MAGIC: &[u8; 8] = b"GZRECP01";
const MAX_FILE_BYTES: u64 = 64 * 1024 * 1024;
pub(super) const MAX_ACTIONS: usize = 1_000_000;

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "snake_case", deny_unknown_fields)]
pub(super) enum RecordedAction {
    Advance,
    Queue(PendingImpulse),
    Transfer { id: u64, promote: bool },
    Group { member: u64 },
    Compact,
    Velocity(crate::protocol::VelocityEdit),
    Retire(u64),
    Forced(Vec<crate::physics::BodyWrench>),
    ImpulseNow(crate::protocol::SpatialImpulse),
    Solver { member: u64 },
    Split { member: u64 },
    Field(crate::physics::StepField),
    Refined(crate::physics::StepField),
    Insert(Body),
    Replace(Body),
    Islands(crate::physics::StepField, Vec<u64>),
    SceneWithSeparation(crate::physics::StepField, bool),
}

pub(super) struct Recorder {
    seeds: [Vec<Body>; 2],
    actions: Vec<RecordedAction>,
    prefixes: [Sha256; 2],
}

impl Recorder {
    pub(super) fn len(&self) -> usize {
        self.actions.len()
    }

    fn extended_hashes(
        &self,
        logs: &[Journal; 2],
        end: [usize; 2],
    ) -> Result<[Sha256; 2], RecoveryError> {
        let mut hashes = self.prefixes.clone();
        for (i, hash) in hashes.iter_mut().enumerate() {
            for entry in &logs[i][..end[i]] {
                bincode::serialize_into(&mut *hash, entry)
                    .map_err(|_| RecoveryError::Format("journal encoding"))?;
            }
        }
        Ok(hashes)
    }

    pub(super) fn compact(&mut self, logs: &[Journal; 2]) -> Result<(), RecoveryError> {
        self.prefixes = self.extended_hashes(logs, logs.each_ref().map(Vec::len))?;
        self.actions.push(RecordedAction::Compact);
        Ok(())
    }
}

#[derive(Debug, thiserror::Error)]
pub enum RecoveryError {
    #[error("recovery file I/O: {0}")]
    Io(#[from] io::Error),
    #[error("invalid recovery file: {0}")]
    Format(&'static str),
    #[error("recovery file serialization: {0}")]
    Codec(#[from] serde_json::Error),
    #[error("coordinator replay failed: {0}")]
    Coordinator(#[from] Error),
    #[error("replayed worker journals differ from the saved barrier")]
    Divergence,
}

#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct Header {
    #[serde(
        default,
        skip_serializing_if = "crate::physics::SimulationStep::is_default"
    )]
    step: crate::physics::SimulationStep,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    ground: Option<crate::physics::GroundPlane>,
    run: u64,
    limit: usize,
    seeds: [Vec<Body>; 2],
    action_count: usize,
    proof: [u8; 32],
}

/// An immutable recovery point. Its digest detects corruption. The caller
/// controls the containing directory and supplies trusted files.
pub struct RecoveryPlan {
    legacy: bool,
    header: Header,
    actions: Vec<RecordedAction>,
}

struct PayloadWriter<W> {
    sink: W,
    remaining: u64,
    hash: Sha256,
}
impl<W: Write> Write for PayloadWriter<W> {
    fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
        if bytes.len() as u64 > self.remaining {
            return Err(io::Error::new(
                io::ErrorKind::FileTooLarge,
                "recovery file limit",
            ));
        }
        let count = self.sink.write(bytes)?;
        self.hash.update(&bytes[..count]);
        self.remaining -= count as u64;
        Ok(count)
    }
    fn flush(&mut self) -> io::Result<()> {
        self.sink.flush()
    }
}

impl RecoveryPlan {
    /// Verify the file length, digest and record boundaries before creating workers.
    pub fn open(path: impl AsRef<Path>) -> Result<Self, RecoveryError> {
        let (magic, bytes) = read_verified(path.as_ref(), &[MAGIC, LEGACY_MAGIC])?;
        let legacy = &magic == LEGACY_MAGIC;
        let payload = bytes
            .strip_suffix(b"\n")
            .ok_or(RecoveryError::Format("incomplete record"))?;
        let mut lines = payload.split(|&c| c == b'\n');
        let header: Header = serde_json::from_slice(lines.next().unwrap_or_default())?;
        if header.limit == 0
            || header.action_count > MAX_ACTIONS
            || (legacy && header.action_count > header.limit.saturating_sub(1).saturating_mul(2))
            || header.seeds.iter().any(|s| s.len() > MAX_BODY_IDS)
            || lines.clone().count() != header.action_count
        {
            return Err(RecoveryError::Format("seed, journal or action count"));
        }
        let actions = lines
            .map(serde_json::from_slice)
            .collect::<Result<Vec<_>, _>>()?;
        Ok(Self {
            legacy,
            header,
            actions,
        })
    }

    pub fn step(&self) -> crate::physics::SimulationStep {
        self.header.step
    }

    pub fn ground(&self) -> Option<crate::physics::GroundPlane> {
        self.header.ground
    }

    pub fn run_id(&self) -> u64 {
        self.header.run
    }

    /// Supply fresh peers for the recorded run, worker IDs and seeds. Fence
    /// the previous coordinator before resuming. Return the published frame
    /// only after every request and reply matches the original journal.
    pub fn resume<P: Peer>(
        self,
        mut spawn: impl FnMut(u64, u8, &[Body]) -> io::Result<P>,
    ) -> Result<Coordinator<P>, RecoveryError> {
        self.resume_with_step(|run, worker, bodies, _step| spawn(run, worker, bodies))
    }

    /// Start replacement peers with the physical interval sealed in the seed journal.
    pub fn resume_with_step<P: Peer>(
        self,
        mut spawn: impl FnMut(u64, u8, &[Body], crate::physics::SimulationStep) -> io::Result<P>,
    ) -> Result<Coordinator<P>, RecoveryError> {
        self.resume_with_ground(|run, worker, bodies, step, _ground| {
            spawn(run, worker, bodies, step)
        })
    }

    /// Restore the immutable terrain descriptor and timestep with both worker seeds.
    pub fn resume_with_ground<P: Peer>(
        self,
        mut spawn: impl FnMut(
            u64,
            u8,
            &[Body],
            crate::physics::SimulationStep,
            Option<crate::physics::GroundPlane>,
        ) -> io::Result<P>,
    ) -> Result<Coordinator<P>, RecoveryError> {
        let h = self.header;
        let peers = [
            spawn(h.run, 0, &h.seeds[0], h.step, h.ground)?,
            spawn(h.run, 1, &h.seeds[1], h.step, h.ground)?,
        ];
        let mut c = Coordinator::new_recorded(h.run, peers, h.limit)?;
        if c.frame.ground() != h.ground {
            return Err(RecoveryError::Format(
                "replacement workers use a different ground plane",
            ));
        }
        if c.frame.step() != h.step {
            return Err(RecoveryError::Format(
                "replacement workers use a different solver interval",
            ));
        }
        for action in self.actions {
            match action {
                RecordedAction::Compact => {
                    c.compact()?;
                    continue;
                }
                RecordedAction::Advance => c.advance()?,
                RecordedAction::ImpulseNow(j) => c.impulse_now(j.id, j.linear, j.angular)?,
                RecordedAction::Velocity(e) => c.set_velocity(e.id, e.linear, e.angular)?,
                RecordedAction::Replace(body) => c.replace_state(body.id, body.state())?,
                RecordedAction::Insert(body) => c.insert_body(body)?,
                RecordedAction::Retire(id) => c.retire(id)?,
                RecordedAction::Forced(w) => c.advance_routed_with_wrenches(&w)?,
                RecordedAction::Queue(p) => c.queue_impulse(p.id, p.impulse)?,
                RecordedAction::Transfer { id, promote } => c.transfer(id, promote)?,
                RecordedAction::Field(f) => c.advance_in_field(f.gravity, &f.wrenches)?,
                RecordedAction::Refined(f) => {
                    let (end, cursor, commands) =
                        c.begin_selected_field(f.gravity, &f.wrenches, true)?;
                    c.complete_step(end, cursor, commands)?
                }
                RecordedAction::SceneWithSeparation(f, fine) => {
                    let (end, cursor, commands) = c.begin_uniform_field(
                        f.gravity,
                        &f.wrenches,
                        crate::adaptive::Resolution::SceneWithSeparation { fine },
                    )?;
                    c.complete_step(end, cursor, commands)?
                }
                RecordedAction::Islands(f, ids) => {
                    if ids.windows(2).any(|pair| pair[0] >= pair[1])
                        || ids.iter().any(|&id| c.frame().body(id).is_none())
                    {
                        return Err(RecoveryError::Format("invalid island step body IDs"));
                    }
                    c.force_motion(f.gravity, &f.wrenches)?;
                    // The action log includes preceding same-tick handoffs.
                    let (end, cursor, commands) = c.begin_resolved_field(
                        f.gravity,
                        &f.wrenches,
                        crate::adaptive::Resolution::Islands(ids),
                    )?;
                    c.complete_step(end, cursor, commands)?
                }
                RecordedAction::Split { member } => c.split_component(member)?,
                RecordedAction::Solver { member } => c.transfer_component(member)?,
                RecordedAction::Group { member } => {
                    let (w, _) = c
                        .frame
                        .body(member)
                        .ok_or(RecoveryError::Format("unknown member"))?;
                    if c.frame.workers[w as usize].snapshot.bodies.len() == 2
                        && c.frame.workers[1 - w as usize].generations.is_empty()
                    {
                        c.transfer_island(w)?
                    } else {
                        c.transfer_group(member)?
                    }
                }
            };
        }
        if c.journal_proof(self.legacy)? != h.proof {
            return Err(RecoveryError::Divergence);
        }
        Ok(c)
    }
}

impl<P: Peer> Coordinator<P> {
    /// Enable explicit durable saves from the initial barrier. Ordinary
    /// coordinators keep only their per-worker recovery journals.
    pub fn new_recorded(run: u64, peers: [P; 2], limit: usize) -> Result<Self, Error> {
        let mut c = Self::new(run, peers, limit)?;
        let seeds = c.journals.each_ref().map(|journal| {
            let Outcome::State(o) = &journal[0].1.outcome else {
                unreachable!("validated seed observation")
            };
            o.snapshot.bodies.clone()
        });
        c.recording = Some(Recorder {
            seeds,
            actions: Vec::new(),
            prefixes: Default::default(),
        });
        Ok(c)
    }

    pub(super) fn commit_action(&mut self) {
        let pending = self
            .pending
            .take()
            .expect("a successful barrier is pending");
        if let Some(operations) = &mut self.recording {
            operations.actions.push(match pending.action {
                Action::Advance => RecordedAction::Advance,
                Action::ImpulseNow(j) => RecordedAction::ImpulseNow(j),
                Action::Velocity(e) => RecordedAction::Velocity(e),
                Action::Replace(body) => RecordedAction::Replace(body),
                Action::Insert(body) => RecordedAction::Insert(body),
                Action::Retire(id) => RecordedAction::Retire(id),
                Action::Forced(w) => RecordedAction::Forced(w),
                Action::Queue(input) => RecordedAction::Queue(input),
                Action::Transfer(t) => RecordedAction::Transfer {
                    id: t.body_id,
                    promote: t.promote,
                },
                Action::Field(field) => RecordedAction::Field(field),
                Action::Refined(field) => RecordedAction::Refined(field),
                Action::Islands(field, ids) => RecordedAction::Islands(field, ids),
                Action::SceneWithSeparation(field, fine) => {
                    RecordedAction::SceneWithSeparation(field, fine)
                }
                Action::Split(member) => RecordedAction::Split { member },
                Action::TransferSolver(t) => RecordedAction::Solver { member: t.ids[0] },
                Action::TransferIsland(t) => RecordedAction::Group { member: t.ids[0] },
            });
        }
    }

    fn journal_proof(&self, legacy: bool) -> Result<[u8; 32], RecoveryError> {
        let end = self
            .pending
            .as_ref()
            .map_or_else(|| self.journals.each_ref().map(Vec::len), |p| p.start);
        let mut hash = Sha256::new();
        let recorder = self
            .recording
            .as_ref()
            .ok_or(RecoveryError::Format("recovery recording disabled"))?;
        if legacy {
            hash.update(b"gz-physics-distributed/recovery/worker-journals/v1");
            for (log, len) in self.journals.iter().zip(end) {
                bincode::serialize_into(&mut hash, &log[..len])
                    .map_err(|_| RecoveryError::Format("journal encoding"))?;
            }
        } else {
            hash.update(b"gz-physics-distributed/recovery/worker-journals/v2");
            for h in recorder.extended_hashes(&self.journals, end)? {
                hash.update(h.finalize());
            }
        }
        // The two per-worker streams alone do not establish the relative order
        // of inputs submitted to different owners before a group transfer.
        bincode::serialize_into(
            &mut hash,
            &(
                self.serial,
                self.frame.tick,
                &self.frame.workers,
                &self.queued,
                Some(&recorder.actions),
            ),
        )
        .map_err(|_| RecoveryError::Format("barrier encoding"))?;
        Ok(hash.finalize().into())
    }

    /// Create a new durable file for the last published barrier, including
    /// queued inputs. An interrupted operation contributes no speculative state.
    pub fn save_recovery(&self, path: impl AsRef<Path>) -> Result<(), RecoveryError> {
        let path = path.as_ref();
        let recorder = self
            .recording
            .as_ref()
            .ok_or(RecoveryError::Format("recovery recording disabled"))?;
        let actions = &recorder.actions;
        let header = Header {
            step: self.frame.step(),
            ground: self.frame.ground(),
            run: self.run,
            limit: self.limit,
            seeds: recorder.seeds.clone(),
            action_count: actions.len(),
            proof: self.journal_proof(false)?,
        };
        write_immutable(path, MAGIC, |out| {
            serde_json::to_writer(&mut *out, &header)?;
            out.write_all(b"\n")?;
            for action in actions {
                serde_json::to_writer(&mut *out, action)?;
                out.write_all(b"\n")?;
            }
            Ok(())
        })
    }
}

pub(crate) fn read_verified(
    path: &Path,
    accepted: &[&[u8; 8]],
) -> Result<([u8; 8], Vec<u8>), RecoveryError> {
    let mut f = File::open(path)?;
    let len = f.metadata()?.len();
    if !(41..=MAX_FILE_BYTES).contains(&len) {
        return Err(RecoveryError::Format("size outside bounds"));
    }
    let mut prefix = [0; 40];
    f.read_exact(&mut prefix)?;
    let magic: [u8; 8] = prefix[..8].try_into().unwrap();
    if !accepted.contains(&&magic) {
        return Err(RecoveryError::Format("unknown version"));
    }
    let mut bytes = Vec::new();
    f.take(len - 40 + 1).read_to_end(&mut bytes)?;
    if bytes.len() as u64 != len - 40 || Sha256::digest(&bytes)[..] != prefix[8..] {
        return Err(RecoveryError::Format("payload digest"));
    }
    Ok((magic, bytes))
}

pub(crate) fn write_immutable(
    path: &Path,
    magic: &[u8; 8],
    encode: impl FnOnce(&mut dyn Write) -> Result<(), RecoveryError>,
) -> Result<(), RecoveryError> {
    let dir = path
        .parent()
        .filter(|p| !p.as_os_str().is_empty())
        .unwrap_or(Path::new("."));
    let mut tmp = tempfile::NamedTempFile::new_in(dir)?;
    tmp.write_all(magic)?;
    tmp.write_all(&[0; 32])?;
    let digest = {
        let mut out = PayloadWriter {
            sink: tmp.as_file_mut(),
            remaining: MAX_FILE_BYTES - 40,
            hash: Sha256::new(),
        };
        // Buffer before both the hash and the file. Individual JSON digits
        // no longer reach the SHA sink as separate writes. The final flush
        // enforces the payload cap before the digest and name are published.
        {
            let mut buffered = BufWriter::new(&mut out);
            encode(&mut buffered)?;
            buffered.flush()?;
        }
        out.hash.finalize()
    };
    tmp.seek(SeekFrom::Start(8))?;
    tmp.write_all(&digest)?;
    tmp.as_file().sync_all()?;
    tmp.persist_noclobber(path).map_err(|e| e.error)?;
    File::open(dir)?.sync_all()?;
    Ok(())
}

#[cfg(test)]
#[test]
fn archive_payload_limit_is_checked_on_the_last_short_buffered_write() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("last-byte.gzpool");
    let error = write_immutable(&path, MAGIC, |out| {
        let block = [0x5a; 64 * 1024];
        let mut remaining = MAX_FILE_BYTES as usize - 40;
        while remaining >= block.len() {
            out.write_all(&block)?;
            remaining -= block.len();
        }
        out.write_all(&block[..remaining])?;
        out.write_all(b"x")?;
        Ok(())
    })
    .unwrap_err();
    assert!(matches!(error,RecoveryError::Io(e) if e.kind()==io::ErrorKind::FileTooLarge));
    assert!(!path.exists());
    assert_eq!(dir.path().read_dir().unwrap().count(), 0);
}
